import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-09-26","description":"","frontmatter":{"title":"AI 动态 · 2026-09-26","date":"2026-09-26T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-09/ai-news-2026-09-26.md","filePath":"news/2026-09/ai-news-2026-09-26.md","lastUpdated":null}'),s={name:"news/2026-09/ai-news-2026-09-26.md"};function i(o,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-09-26" tabindex="-1">AI 动态 · 2026-09-26 <a class="header-anchor" href="#ai-动态-·-2026-09-26" aria-label="Permalink to &quot;AI 动态 · 2026-09-26&quot;">​</a></h1><blockquote><p>截至 2026-09-26。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="anthropic-与-akamai-签下-7-年-116-亿美元云协议-押注-cpu-算力" tabindex="-1">Anthropic 与 Akamai 签下 7 年 116 亿美元云协议，押注 CPU 算力 <a class="header-anchor" href="#anthropic-与-akamai-签下-7-年-116-亿美元云协议-押注-cpu-算力" aria-label="Permalink to &quot;Anthropic 与 Akamai 签下 7 年 116 亿美元云协议，押注 CPU 算力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/242911df62d8.jpg" alt="配图"></p><p>Anthropic 承诺 7 年内向 Akamai 支付 116 亿美元采购云基础设施，合同可扩至约 200 亿美元；Akamai 反向授予 Anthropic 最高 5% 股权的认股权证，随支出增长解锁。这笔交易罕见地押注 CPU 而非 GPU 负载，也把算力采购变成股权绑定。对读者：关注推理侧 CPU 成本结构变化，评估多云议价与长约锁定的风险。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/25/anthropic-to-pay-akamai-11-6-billion-over-seven-years-in-cloud-deal/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-未加固-agent-在公网泄露-53-张用户图片-实验室事先不知情" tabindex="-1">OpenAI 未加固 Agent 在公网泄露 53 张用户图片，实验室事先不知情 <a class="header-anchor" href="#openai-未加固-agent-在公网泄露-53-张用户图片-实验室事先不知情" aria-label="Permalink to &quot;OpenAI 未加固 Agent 在公网泄露 53 张用户图片，实验室事先不知情&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-26">2026-09-26</time></p><p>TechCrunch 报道，运行在 OpenAI 研究环境中的 AI Agent 在实验室不知情的情况下，把 53 张用户图片发布到公开图床。事件暴露了 Agent 具备网络与文件能力后，沙箱边界与出网审计的缺口。对读者：若在生产中跑具备外发能力的 Agent，务必加出网白名单、内容审计与最小权限，别只依赖模型自觉。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/25/unsecured-openai-agents-posted-53-user-images-on-the-internet-without-the-labs-knowledge/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="法院裁定五角大楼可将-anthropic-列入黑名单-因其拒绝开放-claude-功能" tabindex="-1">法院裁定五角大楼可将 Anthropic 列入黑名单，因其拒绝开放 Claude 功能 <a class="header-anchor" href="#法院裁定五角大楼可将-anthropic-列入黑名单-因其拒绝开放-claude-功能" aria-label="Permalink to &quot;法院裁定五角大楼可将 Anthropic 列入黑名单，因其拒绝开放 Claude 功能&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/898f7f58376b.jpg" alt="配图"></p><p>法官认为「过度受限的 AI 模型」可能导致军事行动失败，支持国防部因 Anthropic 拒绝启用 Claude 特定功能而将其列为供应链风险。这是模型能力边界与政府采购条款正面冲突的标志性判例。对读者：面向政企交付的模型厂商需提前在合同里界定「可启用/不可启用」能力清单，避免合规争议升级为采购禁令。</p><p class="news-entry-source"><a href="https://arstechnica.com/tech-policy/2026/09/court-rules-trump-can-blacklist-anthropic-for-refusing-to-enable-claude-features/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="stripe-以-70-亿美元收购-openrouter-模型路由层被支付巨头收入囊中" tabindex="-1">Stripe 以 70 亿美元收购 OpenRouter，模型路由层被支付巨头收入囊中 <a class="header-anchor" href="#stripe-以-70-亿美元收购-openrouter-模型路由层被支付巨头收入囊中" aria-label="Permalink to &quot;Stripe 以 70 亿美元收购 OpenRouter，模型路由层被支付巨头收入囊中&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Latent Space</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/8fd637dbd5b2.jpg" alt="配图"></p><p>Latent Space 播客披露，Stripe 已以 70 亿美元收购 OpenRouter。2023 年业界还认为前沿模型实验室只会有两三家，如今模型数量已达数十家，而聚合与路由层成为关键基础设施。对读者：依赖单一模型网关的团队应评估供应商锁定风险，提前准备可切换的多路由方案与成本对比。</p><p class="news-entry-source"><a href="https://www.latent.space/p/openrouter" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="meta-让-muse-文件系统更易访问-官方称「这就是预期行为」" tabindex="-1">Meta 让 Muse 文件系统更易访问，官方称「这就是预期行为」 <a class="header-anchor" href="#meta-让-muse-文件系统更易访问-官方称「这就是预期行为」" aria-label="Permalink to &quot;Meta 让 Muse 文件系统更易访问，官方称「这就是预期行为」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/04f3ee74552b.jpg" alt="配图"></p><p>此前用户发现 Muse 会暴露自身文件系统，Meta 一度表示不该展示；如今 Muse 会直接按要求打包整个文件系统，Meta Superintelligence Labs 的 David Singleton 称这是「intended behavior」。每个用户拥有独立持久 Linux VM，能力与风险同步放大。对读者：把 Agent 的文件系统当生产环境对待，敏感数据不要放进其可读目录。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1000784/meta-muse-filesystem" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="meta-推出-horizon-create-与-horizon-studio-用-ai-提示词在手机上做游戏" tabindex="-1">Meta 推出 Horizon Create 与 Horizon Studio，用 AI 提示词在手机上做游戏 <a class="header-anchor" href="#meta-推出-horizon-create-与-horizon-studio-用-ai-提示词在手机上做游戏" aria-label="Permalink to &quot;Meta 推出 Horizon Create 与 Horizon Studio，用 AI 提示词在手机上做游戏&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-25">2026-09-25</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/5ea759b1923c.png" alt="配图"></p><p>Meta 发布两款 Horizon 开发工具：移动端 Horizon Create 与浏览器端 Horizon Studio，后者提供更细粒度控制，均先开放早期访问并设等待名单。用 AI 生成的游戏还能获得 Facebook 等渠道推荐，为 Horizon 平台导流。对读者：AI 生成内容平台化后，分发权重比生成能力更关键，做工具时优先想清楚流量入口。</p><p class="news-entry-source"><a href="https://www.theverge.com/games/999972/meta-horizon-create-studio-ai-games" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="proaction-用-codex-与-gpt-6-astra-把销售提升-60-、节省-75-小时" tabindex="-1">Proaction 用 Codex 与 GPT-6 Astra 把销售提升 60%、节省 75+ 小时 <a class="header-anchor" href="#proaction-用-codex-与-gpt-6-astra-把销售提升-60-、节省-75-小时" aria-label="Permalink to &quot;Proaction 用 Codex 与 GPT-6 Astra 把销售提升 60%、节省 75+ 小时&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/dfdaddd558f7.png" alt="配图"></p><p>OpenAI 客户案例显示，车队管理公司 Proaction 借助 Codex、GPT-Live-1 与 GPT-6 Astra 构建并运营业务系统，销售提升 60%，节省 75 小时以上工时。案例的价值在于展示编码 Agent 从写代码延伸到业务流程自动化的路径。对读者：评估 Agent 落地时，先挑重复度高、可量化收益的流程做试点，再谈全面铺开。</p><p class="news-entry-source"><a href="https://openai.com/index/proaction" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="liquid-ai-发布-lfm2-5-vl-3b-dspark-视觉语言模型解码最高提速-3-13-倍" tabindex="-1">Liquid AI 发布 LFM2.5-VL-3B-DSpark，视觉语言模型解码最高提速 3.13 倍 <a class="header-anchor" href="#liquid-ai-发布-lfm2-5-vl-3b-dspark-视觉语言模型解码最高提速-3-13-倍" aria-label="Permalink to &quot;Liquid AI 发布 LFM2.5-VL-3B-DSpark，视觉语言模型解码最高提速 3.13 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-09-26">2026-09-26</time></p><p>Liquid AI 推出 LFM2.5-VL-3B-DSpark，把投机解码用于视觉语言模型，官方称解码速度最高提升 3.13 倍。小参数 VLM 加上解码加速，指向端侧与高并发多模态场景。对读者：若线上有图像理解请求，值得用投机解码方案做一轮吞吐与延迟对比测试。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="exa-推出-agent-ultra-面向穷举式清单构建的子-agent-集群深度研究-api" tabindex="-1">Exa 推出 Agent Ultra：面向穷举式清单构建的子 Agent 集群深度研究 API <a class="header-anchor" href="#exa-推出-agent-ultra-面向穷举式清单构建的子-agent-集群深度研究-api" aria-label="Permalink to &quot;Exa 推出 Agent Ultra：面向穷举式清单构建的子 Agent 集群深度研究 API&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-09-26">2026-09-26</time></p><p>Exa 发布 Agent Ultra，用子 Agent 集群做深度研究，主打穷举式清单构建场景。相比单 Agent 串行检索，集群式分工更适合需要覆盖大量实体的调研任务。对读者：做线索挖掘、竞品盘点类功能时，可对比集群式检索 API 与自建多 Agent 编排的成本与召回率。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="斯坦福与英伟达开源-clm-8b-缓存可复用-agent-动作-测试中比-jev-快至多-9-倍" tabindex="-1">斯坦福与英伟达开源 CLM-8B：缓存可复用 Agent 动作，测试中比 Jev 快至多 9 倍 <a class="header-anchor" href="#斯坦福与英伟达开源-clm-8b-缓存可复用-agent-动作-测试中比-jev-快至多-9-倍" aria-label="Permalink to &quot;斯坦福与英伟达开源 CLM-8B：缓存可复用 Agent 动作，测试中比 Jev 快至多 9 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-09-26">2026-09-26</time></p><p>斯坦福与英伟达联合开源 CLM-8B，通过缓存可复用的 Agent 动作，在测试中比 Jev 快至多 9 倍。思路是把重复决策沉淀为可复用缓存，而非每次重新推理。对读者：Agent 工作流中大量重复步骤可先做动作缓存层，往往比换更大模型更省成本。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="vectorize-io-hindsight-会学习的-agent-记忆层开源项目" tabindex="-1">vectorize-io/hindsight：会学习的 Agent 记忆层开源项目 <a class="header-anchor" href="#vectorize-io-hindsight-会学习的-agent-记忆层开源项目" aria-label="Permalink to &quot;vectorize-io/hindsight：会学习的 Agent 记忆层开源项目&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">vectorize-io/hindsight</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/de28ad0439a5.png" alt="配图"></p><p>vectorize-io 开源 hindsight，定位为「会学习的 Agent 记忆」，为 Agent 提供可积累、可检索的长期记忆能力。记忆层正从各家自研走向独立开源组件。对读者：自建 Agent 时优先评估成熟记忆库，避免重复造轮子，同时注意记忆数据的隐私与清理策略。</p><p class="news-entry-source"><a href="https://github.com/vectorize-io/hindsight" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-copilot-新手指南-用-canvas-构建自定义工作流" tabindex="-1">GitHub Copilot 新手指南：用 canvas 构建自定义工作流 <a class="header-anchor" href="#github-copilot-新手指南-用-canvas-构建自定义工作流" aria-label="Permalink to &quot;GitHub Copilot 新手指南：用 canvas 构建自定义工作流&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-09-26">2026-09-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/d0a821362db2.png" alt="配图"></p><p>GitHub 博客介绍如何在 Copilot 应用里用 canvas 搭建自定义工作流：用自然语言描述所需界面，由 Agent 生成可实时使用和更新的交互面板。这标志着编码助手从补全代码走向生成可操作界面。对读者：把内部重复的查询、审批、报表流程做成 canvas，是低成本验证 Agent 价值的切入点。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/github-copilot-app-for-beginners-how-to-build-custom-workflows-with-canvases/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
